@Test
public void movieRestTest() throws Exception {
    final WebClient webClient = WebClient.create(base.toExternalForm(), singletonList(new JohnzonProvider<>()), singletonList(new LoggingFeature()), null);
    // Testing REST endpoint that returns the value of a JWT claim
    String responsePayload = webClient.reset().path("/rest/bookstore/me").header("Authorization", "Bearer " + token(true)).get(String.class);
    LOGGER.info("responsePayload = " + responsePayload);
    assertEquals("alice", responsePayload);
    // Testing REST endpoint with group claims manager
    Book newBook = new Book(1, "The Lord of the Rings", "J.R.R.Tolkien");
    Response response = webClient.reset().path("/rest/bookstore").header("Content-Type", "application/json").header("Authorization", "Bearer " + token(true)).post(newBook);
    LOGGER.info("responseCode = " + response.getStatus());
    assertEquals(204, response.getStatus());
    // Testing REST endpoint with group claims reader
    Collection<? extends Book> books = webClient.reset().path("/rest/bookstore").header("Content-Type", "application/json").header("Authorization", "Bearer " + token(false)).getCollection(Book.class);
    LOGGER.info(books.toString());
    assertEquals(1, books.size());
    // Should return a 403 since POST requires group claim manager but provided token has only reader.
    Book secondBook = new Book(2, "Mistborn: The Final Empire", "Brandon Sanderson");
    Response responseWithError = webClient.reset().path("/rest/bookstore").header("Content-Type", "application/json").header("Authorization", "Bearer " + token(false)).post(secondBook);
    LOGGER.info("responseCode = " + responseWithError.getStatus());
    assertEquals(403, responseWithError.getStatus());
    // Should return a 401 since the POST request lacks the Authorization header
    Response responseWith401Error = webClient.reset().path("/rest/bookstore").header("Content-Type", "application/json").post(new Book());
    LOGGER.info("responseCode = " + responseWith401Error.getStatus());
    assertEquals(401, responseWith401Error.getStatus());
}

