@Test
public void test() throws Exception {
    final TomEE keyServer = TomEE.microprofile().add("webapps/ROOT/WEB-INF/beans.xml", "").add("webapps/ROOT/WEB-INF/lib/app.jar", Archive.archive().add(HttpKeyAccessTimeoutTest.class).add(KeyServer.KeysService.class).add(KeyServer.class).add(Tokens.class).asJar()).add("webapps/ROOT/WEB-INF/lib/jose.jar", JarLocation.jarLocation(JWSSigner.class)).build();
    final TomEE tomee = TomEE.microprofile().add("webapps/ROOT/WEB-INF/beans.xml", "").add("webapps/ROOT/WEB-INF/lib/app.jar", Archive.archive().add(HttpKeyAccessTimeoutTest.class).add(MicroProfileWebApp.class).add(MicroProfileWebApp.ColorService.class).add(MicroProfileWebApp.Api.class).add(KeyServer.class).add("META-INF/microprofile-config.properties", new PublicKeyLocation().initialRetryDelay(500, TimeUnit.MILLISECONDS).accessTimeout(1, TimeUnit.SECONDS).refreshInterval(1, TimeUnit.HOURS).location(keyServer.toURI().resolve("/keys/publicKey")).build()).toJar()).build();
    /*
         * Ensure we do reject JWTs we don't know
         */
    final Tokens unknownKey = Tokens.rsa(2048, 256);
    /*
         * The keypair for the server.  This won't be returned TomEE and calls won't succeed till
         * we call GET /keys/release
         */
    final String privateKey = IO.slurp(keyServer.toURI().resolve("/keys/privateKey").toURL());
    final Tokens publicKey = Tokens.fromPrivateKey(privateKey);
    /*
         * Verify calls do fail as noted above
         */
    Runner.threads(100).run(() -> assertKeys(tomee, unknownKey, publicKey, 401)).assertNoExceptions();
    /*
         * Unblock the key server and allow it to communicate the public key to TomEE
         */
    IO.slurp(keyServer.toURI().resolve("/keys/release").toURL());
    /*
         * Verify calls now succeed
         */
    Runner.threads(100).run(() -> assertKeys(tomee, unknownKey, publicKey, 200)).assertNoExceptions();
}

