@Test
public void customScript() throws Exception {
    Assume.assumeFalse(System.getProperty("java.version").startsWith("1.7"));
    // we use a dynamic InputStream to be able to simulate commands without hacking System.in
    final Input input = new Input();
    final Semaphore reloaded = new Semaphore(0);
    final CountDownLatch started = new CountDownLatch(1);
    final TomEEEmbeddedMojo mojo = new TomEEEmbeddedMojo() {

        @Override
        protected Scanner newScanner() {
            return new Scanner(input);
        }
    };
    mojo.classpathAsWar = true;
    mojo.httpPort = NetworkUtil.getNextAvailablePort();
    mojo.ssl = false;
    mojo.webResourceCached = false;
    mojo.jsCustomizers = singletonList("var File = Java.type('java.io.File');" + "var FileWriter = Java.type('java.io.FileWriter');" + "var out = new File(catalinaBase, 'conf/app.conf');" + "var writer = new FileWriter(out);" + "writer.write('test=ok');" + "writer.close();");
    mojo.setLog(new // not the best solution but fine for now...
    SystemStreamLog() {

        @Override
        public void info(final CharSequence charSequence) {
            final String string = charSequence.toString();
            if (string.startsWith("TomEE embedded started on") || string.equals("can't start TomEE")) {
                started.countDown();
            } else if (string.contains("Redeployed /")) {
                reloaded.release();
            }
            super.info(charSequence);
        }
    });
    CountDownLatch stopped = null;
    try {
        stopped = doStart(started, mojo);
        final File appConf = new File(System.getProperty("catalina.base"), "conf/app.conf");
        assertTrue(appConf.exists());
        assertEquals("ok", IO.readProperties(appConf).getProperty("test", "ko"));
    } finally {
        input.write("exit");
        if (stopped != null) {
            stopped.await(5, TimeUnit.MINUTES);
        }
        input.close();
    }
}

@Test
public void checkParsing() {
    assertEquals(asList("-Dfoo=bar"), Args.parse("-Dfoo=bar"));
    assertEquals(asList("-Dfoo=bar", "-D2=3", "-Dty"), Args.parse("-Dfoo=bar -D2=3 -Dty"));
    assertEquals(asList("-Dfoo=bar", "-D2=3", "-Dty"), Args.parse("-Dfoo=bar    -D2=3        -Dty"));
    assertEquals(asList("-Dkey with space=value"), Args.parse("\"-Dkey with space=value\""));
    assertEquals(asList("-Dkey with space"), Args.parse("\"-Dkey with space\""));
    assertEquals(asList("-Dkey with space=value with space"), Args.parse("\"-Dkey with space=value with space\""));
    assertEquals(asList("-Dfoo1=bar", "-Dkey with space=value with space", "-Dfoo=bar"), Args.parse("-Dfoo1=bar \"-Dkey with space=value with space\" -Dfoo=bar"));
}

