    assertEquals("Jan 02, 1970 my.class.Name aMethod\nFINER: test message\n", new LocalFileHandler.PatternFormatter("%1$tb %1$td, %1$tY %1$tl:%1$tM:%1$tS %1$Tp %2$s%n%4$s: %5$s%6$s%n", Locale.ENGLISH).format(record).replace("\r", "").replaceFirst("1970.*my", /*skip time*/
    "1970 my"));
    // simple
    assertEquals("test message\n", new LocalFileHandler.PatternFormatter("%5$s%n", Locale.ENGLISH).format(record).replace("\r", ""));
    final String custom = new LocalFileHandler.PatternFormatter("%1$tY-%1$tM-%1$td %1$tT [%4$5s][%7$s] %5$s%6$s%n", Locale.ENGLISH).format(record).replace("\r", "");
